def solve_prism(n):
    # Prism graph Y_n = C_n \square P_2
    # States for rung i: (u_i, v_i) \in {(0,0), (1,0), (0,1)}
    # We can use a transfer matrix.
    import numpy as np

    # States: 0: (0,0), 1: (1,0), 2: (0,1)
    T = np.zeros((3, 3), dtype=object)
    # T[i][j] = 1 if state i can be followed by state j
    # State i: (u_i, v_i), State j: (u_{i+1}, v_{i+1})
    # Constraints: u_i*u_{i+1} = 0 and v_i*v_{i+1} = 0
    for i in range(3):
        u_i = 1 if i == 1 else 0
        v_i = 1 if i == 2 else 0
        for j in range(3):
            u_j = 1 if j == 1 else 0
            v_j = 1 if j == 2 else 0
            if u_i * u_j == 0 and v_i * v_j == 0:
                T[i][j] = 1

    # The number of independent sets is Trace(T^n)
    T_n = np.linalg.matrix_power(T, n)
    return np.trace(T_n)

# Since T has small size, we can just use integer matrix multiplication
def mat_mul(A, B):
    C = [[0]*3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            for k in range(3):
                C[i][j] += A[i][k] * B[k][j]
    return C

def mat_pow(A, p):
    res = [[0]*3 for _ in range(3)]
    for i in range(3): res[i][i] = 1
    while p > 0:
        if p % 2 == 1: res = mat_mul(res, A)
        A = mat_mul(A, A)
        p //= 2
    return res

